395	<script>
396	(function () {
397	  // The minimal animation stylesheet each asset depends on. Embedded inside the
398	  // copied <svg> so the asset stays self-animating when dropped into any project.
399	  var ANIM_CSS = [
400	    '@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}',
401	    '@keyframes blink{0%,92%,100%{transform:scaleY(1)}96%{transform:scaleY(.1)}}',
402	    '@keyframes sway{0%,100%{transform:rotate(-4deg)}50%{transform:rotate(4deg)}}',
403	    '@keyframes pop{0%{transform:scale(0);opacity:0}60%{transform:scale(1.15);opacity:1}100%{transform:scale(1)}}',
404	    '@keyframes draw{to{stroke-dashoffset:0}}',
405	    '@keyframes confetti{0%{transform:translateY(0) rotate(0);opacity:1}100%{transform:translateY(-46px) rotate(220deg);opacity:0}}',
406	    '@keyframes spin{to{transform:rotate(360deg)}}',
407	    '@keyframes pulse{0%,100%{transform:scale(1);opacity:.9}50%{transform:scale(1.12);opacity:.5}}',
408	    '@keyframes wiggle{0%,100%{transform:rotate(0)}25%{transform:rotate(8deg)}75%{transform:rotate(-8deg)}}',
409	    '@keyframes orbit{to{transform:rotate(-360deg)}}',
410	    '@keyframes rise{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}',
411	    '@keyframes twinkle{0%,100%{opacity:.2;transform:scale(.6)}50%{opacity:1;transform:scale(1)}}',
412	    '@keyframes heartbeat{0%,100%{transform:scale(1)}15%{transform:scale(1.13)}30%{transform:scale(1)}45%{transform:scale(1.08)}}',
413	    '.a-float{animation:float 4s ease-in-out infinite;transform-origin:center}',
414	    '.a-blink{animation:blink 5s ease-in-out infinite;transform-origin:center}',
415	    '.a-sway{animation:sway 4.5s ease-in-out infinite;transform-origin:50% 90%}',
416	    '.a-pop{animation:pop .7s cubic-bezier(.2,1.3,.4,1) both}',
417	    '.a-spin{animation:spin 1.4s linear infinite;transform-origin:center}',
418	    '.a-pulse{animation:pulse 2.6s ease-in-out infinite;transform-origin:center}',
419	    '.a-wiggle{animation:wiggle 3.5s ease-in-out infinite;transform-origin:50% 80%}',
420	    '.a-orbit{animation:orbit 6s linear infinite;transform-origin:center}',
421	    '.a-rise{animation:rise 3s ease-in-out infinite;transform-origin:center}',
422	    '.a-twinkle{animation:twinkle 2s ease-in-out infinite;transform-origin:center}',
423	    '.a-heartbeat{animation:heartbeat 2.4s ease-in-out infinite;transform-origin:center}',
424	    '.draw{stroke-dasharray:90;stroke-dashoffset:90;animation:draw 1s ease-out .25s forwards}',
425	    '.conf{animation:confetti 1.3s ease-out infinite}',
426	    '.conf:nth-child(odd){animation-duration:1.6s}',
427	    '@media (prefers-reduced-motion:reduce){.a-float,.a-blink,.a-sway,.a-pop,.a-spin,.a-pulse,.a-wiggle,.a-orbit,.a-rise,.a-twinkle,.a-heartbeat,.conf{animation:none}.draw{stroke-dashoffset:0}}'
428	  ].join('');
429	
430	  // Build standalone, self-animating SVG markup for one card's stage <svg>.
431	  function buildSvg(svg) {
432	    var clone = svg.cloneNode(true);
433	    var style = document.createElementNS('http://www.w3.org/2000/svg', 'style');
434	    style.textContent = ANIM_CSS;
435	    clone.insertBefore(style, clone.firstChild);
436	    if (!clone.getAttribute('xmlns')) clone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
437	    return clone.outerHTML.replace(/></g, '>\n<');
438	  }
439	
440	  var toast = document.getElementById('toast'), toastTimer;
441	  function showToast(msg) {
442	    toast.textContent = msg;
443	    toast.classList.add('show');
444	    clearTimeout(toastTimer);
445	    toastTimer = setTimeout(function () { toast.classList.remove('show'); }, 1800);
446	  }
447	
448	  var COPY_IC = '<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="11" height="11" rx="2"/><path d="M5 15V5a2 2 0 0 1 2-2h10"/></svg>';
449	  var DONE_IC = '<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M5 13l4 4L19 7"/></svg>';
450	
451	  function fallbackCopy(text) {
452	    var ta = document.createElement('textarea');
453	    ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
454	    document.body.appendChild(ta); ta.select();
455	    var ok = false; try { ok = document.execCommand('copy'); } catch (e) {}
456	    document.body.removeChild(ta); return ok;
457	  }
458	
459	  document.querySelectorAll('.card').forEach(function (card) {
460	    var svg = card.querySelector('.stage svg');
461	    if (!svg) return;
462	    var name = (card.querySelector('.name') || {}).textContent || 'asset';
463	    var btn = document.createElement('button');
464	    btn.type = 'button';
465	    btn.className = 'copy-btn';
466	    btn.innerHTML = COPY_IC + '<span>Copy SVG</span>';
467	    btn.setAttribute('aria-label', 'Copy SVG markup for ' + name);
468	
469	    btn.addEventListener('click', function () {
470	      var markup = buildSvg(svg);
471	      var done = function () {
472	        btn.classList.add('done');
473	        btn.innerHTML = DONE_IC + '<span>Copied!</span>';
474	        showToast('SVG copied — paste it anywhere');
475	        setTimeout(function () {
476	          btn.classList.remove('done');
477	          btn.innerHTML = COPY_IC + '<span>Copy SVG</span>';
478	        }, 1800);
479	      };
480	      if (navigator.clipboard && navigator.clipboard.writeText) {
481	        navigator.clipboard.writeText(markup).then(done, function () {
482	          if (fallbackCopy(markup)) done(); else showToast('Copy failed — select manually');
483	        });
484	      } else {
485	        if (fallbackCopy(markup)) done(); else showToast('Copy failed — select manually');
486	      }
487	    });
488	
489	    card.querySelector('.body').appendChild(btn);
490	  });
491	
492	  // ---- Journey-stage filtering ----
493	  var cards = Array.prototype.slice.call(document.querySelectorAll('.card'));
494	  var chips = Array.prototype.slice.call(document.querySelectorAll('.filterbar .chip'));
495	  var countEl = document.getElementById('fbCount');
496	  var emptyNote = document.getElementById('emptyNote');
497	
498	  function applyFilter(filter) {
499	    var shown = 0;
500	    cards.forEach(function (card) {
501	      var match = filter === 'all' || card.getAttribute('data-cat') === filter;
502	      card.classList.toggle('hide', !match);
503	      if (match) shown++;
504	    });
505	    chips.forEach(function (chip) {
506	      chip.setAttribute('aria-pressed', String(chip.getAttribute('data-filter') === filter));
507	    });
508	    countEl.textContent = shown + (shown === 1 ? ' asset' : ' assets');
509	    emptyNote.style.display = shown === 0 ? 'block' : 'none';
510	  }
511	
512	  chips.forEach(function (chip) {
513	    chip.addEventListener('click', function () { applyFilter(chip.getAttribute('data-filter')); });
514	  });
515	})();
516	</script>
517	</body>
518	</html>
